  function header(){return `<div class="cw-head"><div><div class="eyebrow">课件制作 / COURSEWARE</div><h1>图论基础 · 2026 春季课件</h1><p class="muted">基于第 2 章章节备课生成 · v1.0 · 最近保存 2 分钟前</p><div class="cw-context"><span class="cw-chip">第 2 章 · 6 学时</span><span class="cw-chip">来源：章节备课工作台</span><span class="cw-chip warn">2 页待教师核对</span></div></div><div class="cw-head-actions"><button class="btn secondary" onclick="cwPreview()">预览</button><button class="btn secondary" onclick="cwExport()">导出</button><button class="btn primary" onclick="cwSave()">保存课件</button></div></div><div class="cw-tabs"><button class="cw-tab ${mode==='outline'?'active':''}" onclick="cwMode('outline')">章节编排</button><button class="cw-tab ${mode==='editor'?'active':''}" onclick="cwMode('editor')">页面编辑</button><button class="cw-tab" onclick="cwMode('sources')">来源与版本</button></div>`}
