  header=function(){return `<div class="cw-head"><div><div class="eyebrow">课件制作 / COURSEWARE</div><h1>图论基础 · 2026 春季课件</h1><p class="muted">当前章节即当前课件 · 基于章节备课工作台内容生成 · v1.0</p></div><div class="cw-head-actions"><button class="btn secondary" onclick="cwPreview()">预览</button><button class="btn secondary" onclick="cwExport()">导出</button><button class="btn secondary cw-version-top" onclick="cwApply('已打开页面版本 v1.0')">页面版本 v1.0⌄</button><button class="btn primary" onclick="cwSave()">保存课件</button></div></div>`};
  function editorTabs(){return `<div class="cw-tabs"><button class="cw-tab ${mode==='ppt'?'active':''}" onclick="cwMode('ppt')">PPT 编辑</button><button class="cw-tab ${mode==='handout'?'active':''}" onclick="cwMode('handout')">讲义编辑</button></div>`}
  function chapterSwitcher(){return `<section class="cw-chapter-bar"><div class="cw-chapter-meta"><div><span class="cw-muted">当前课件章节</span><b>第二章 · 图论基础</b><small>第 10 周 · 6 学时 · 91 页参考课件</small></div><span class="tag ok">已关联备课</span></div><div class="cw-chapter-picker"><button class="cw-chapter-arrow" onclick="cwChapter(-1)" aria-label="上一章节">‹</button><div class="cw-chapter-rail"><button class="cw-chapter-pill" onclick="cwChapterSelect('第一章 · 集合与关系')"><b>第一章 · 集合与关系</b><small>第 2 周 · 4 学时</small><i>已完成</i></button><button class="cw-chapter-pill active"><b>第二章 · 图论基础</b><small>第 10 周 · 6 学时</small><i>57 / 91 页已生成</i></button><button class="cw-chapter-pill" onclick="cwChapterSelect('第三章 · 树与特殊图')"><b>第三章 · 树与特殊图</b><small>第 11 周 · 6 学时</small><i>待生成</i></button></div><button class="cw-chapter-arrow" onclick="cwChapter(1)" aria-label="下一章节">›</button></div></section>`}
  function revisedEditor(){const s=slides[activeSlide];return `<div class="cw-editor"><aside class="cw-panel cw-thumb-panel"><div class="cw-thumb-head"><h3>页面导航</h3><button class="icon-btn" onclick="cwAddSlide()">＋</button></div><div class="cw-muted" style="margin-top:4px">第二章 · 图论基础 · ${slides.length} / 91 页</div><div class="cw-thumb-list">${slides.map((x,i)=>`<div class="cw-thumb ${i===activeSlide?'active':''}" onclick="cwSlide(${i})"><div class="thumb-top"><span class="thumb-type">${x[2]}</span><span class="cw-muted">${x[0]}</span></div><small>${x[1]}</small></div>`).join('')}</div><button class="btn secondary" style="width:100%;margin-top:12px" onclick="cwAddSlide()">＋ 新增页面</button></aside><section class="cw-panel cw-canvas-panel"><div class="cw-editor-toolbar"><div><b>PPT 编辑画布</b><div class="cw-muted">第 ${s[0]} 页 · ${s[1]} · 点击画布元素进行编辑</div></div><div class="cw-toolbar-actions"><button class="btn secondary" onclick="cwRegenerate()">AI 重写本页</button></div></div><div class="cw-slide cw-real-slide" contenteditable="true"><span class="cw-slide-kicker">CHAPTER 02 · GRAPH THEORY</span><h2>${s[1]}</h2><ul class="cw-bullets"><li>掌握图的基本概念、结点集与边集的表示方法</li><li>理解邻接矩阵与关联矩阵，并能完成简单转换</li><li>结合城市交通网络案例，解释图模型的应用价值</li></ul>${activeSlide===2?'<div class="cw-diagram"><strong>图示组件 · 可在 PPT 画布中编辑</strong><span class="cw-node">V</span><span class="cw-line">────</span><span class="cw-node">E</span><small>结点集与边集的关系图</small></div>':''}<span class="cw-edit-hint">拖动元素移动位置 · 双击文本编辑</span></div><div class="cw-slide-meta"><div class="cw-meta-head"><b>来源与教学关联</b><button class="btn secondary" onclick="cwSource()">查看原文上下文</button></div><div class="cw-meta-grid"><div class="cw-source-card"><b>离散数学教材.pdf</b><small>第 4 章 · 图论基础 · 第 4–8 页</small></div><div class="cw-source-card"><b>第二章章节备课</b><small>重点难点、例题与互动 · 已确认</small></div><div class="cw-source-card"><b>教学关联</b><small>知识点：图的定义 · 目标 2 · 能力指标 A1</small></div></div></div><div class="cw-canvas-footer"><span>16:9 · 主题：学术青绿</span><span>自动保存已开启</span></div></section><aside class="cw-rail"><section class="cw-panel cw-ai-assistant"><div class="cw-ai-title"><div><h3>AI 课件助手</h3><span class="cw-muted">辅助修改当前 PPT 页</span></div><span class="cw-chip">当前页 ${s[0]}</span></div><div class="cw-ai-suggestions"><div class="cw-ai-item"><b>优化表达</b><p>将第 2 条要点改写得更适合课堂讲解。</p><div class="cw-ai-actions"><button class="btn primary" onclick="cwApply('已应用表达优化候选')">生成候选</button></div></div><div class="cw-ai-item"><b>插入页面图表</b><p>把“结点集—边集”替换为关系图，保持在当前页内。</p><div class="cw-ai-actions"><button class="btn secondary" onclick="cwApply('图表组件已插入当前 PPT 页')">插入图表</button></div></div></div><div class="cw-ai-compose"><textarea placeholder="例如：把这一页改成课堂提问式"></textarea><button class="btn primary" onclick="cwApply('AI 正在生成本页修改候选')">发送</button></div></section></aside></div>`}
  let handoutView='edit',activeHandout=2;
  const handoutSections=[['01','问题引入','PPT 01–02','通过哥尼斯堡七桥问题引出图模型。'],['02','图的定义','PPT 03','图 G=(V,E) 由结点集 V 和边集 E 构成。'],['03','图的表示方法','PPT 04–05','介绍邻接矩阵、关联矩阵和图形化表示。'],['04','握手定理','PPT 06–08','从度数总和说明握手定理并完成例题。'],['05','综合案例','PPT 09–12','将城市交通网络抽象为图模型。']];
  function handout(){const h=handoutSections[activeHandout]||handoutSections[0];const preview=handoutView==='read';return `<div class="cw-handout-layout"><aside class="cw-panel cw-handout-nav"><div class="cw-handout-nav-head"><h3>讲义导航</h3><span class="cw-chip">5 个小节</span></div><div class="cw-muted" style="margin:4px 0 10px">第二章 · 图论基础</div>${handoutSections.map((x,i)=>`<button class="cw-handout-nav-item ${i===activeHandout?'active':''}" onclick="cwHandoutSelect(${i})"><span class="cw-handout-num">${x[0]}</span><span><b>${x[1]}</b><small>${x[2]}</small></span><em>${i===2?'已编辑':i===3?'待核对':'已关联'}</em></button>`).join('')}</aside><main class="cw-handout-main"><section class="cw-panel cw-ppt-reference"><div class="cw-reference-head"><div><b>PPT 参考页 · ${h[2]}</b><span class="cw-muted">${h[1]}</span></div><div><button class="btn secondary" onclick="cwSlide(${activeHandout})">在 PPT 编辑中打开</button><button class="btn secondary" onclick="cwApply('PPT 要点已插入讲义')">将 PPT 要点插入讲义</button></div></div><div class="cw-mini-slide"><span class="cw-slide-kicker">CHAPTER 02 · GRAPH THEORY</span><h2>${h[1]}</h2><p>${h[3]}</p><div class="cw-mini-slide-foot">当前页面作为讲义编辑参考 · 不会直接覆盖讲义正文</div></div></section><section class="cw-panel cw-handout-editor"><div class="cw-editor-toolbar"><div><b>${h[0]} · ${h[1]}</b><div class="cw-muted">关联 ${h[2]} · 来源：第二章章节备课</div></div><div class="cw-handout-view-toggle"><button class="cw-tool ${!preview?'active':''}" onclick="cwHandoutView('edit')">编辑</button><button class="cw-tool ${preview?'active':''}" onclick="cwHandoutView('read')">阅读预览</button><button class="btn primary" onclick="cwApply('讲义已保存')">保存讲义</button></div></div>${preview?`<article class="cw-handout-reading"><h2>${h[1]}</h2><h4>讲解目标</h4><p>理解图由结点集和边集构成，能够将现实网络抽象为图模型。</p><h4>教师讲解正文</h4><p>${h[3]} 在课堂上可结合教材中的图示，先说明对象与关系，再引出形式化定义。</p><h4>课堂提示</h4><p>提问：城市交通网络中的地铁站和线路分别对应图中的什么？</p><h4>本节小结</h4><p>图由结点集 V 和边集 E 构成，可使用图形、邻接矩阵和关联矩阵表示。</p></article>`:`<div class="cw-handout-fields"><label>讲解目标<textarea>理解图由结点集和边集构成，能够将现实网络抽象为图模型。</textarea></label><label>教师讲解正文<textarea>${h[3]} 在课堂上可结合教材中的图示，先说明对象与关系，再引出形式化定义。</textarea></label><label>课堂提示<textarea>提问：城市交通网络中的地铁站和线路分别对应图中的什么？</textarea></label><label>本节小结<textarea>图由结点集 V 和边集 E 构成，可使用图形、邻接矩阵和关联矩阵表示。</textarea></label></div>`}</section><section class="cw-slide-meta"><div class="cw-meta-head"><b>来源与教学关联</b><button class="btn secondary" onclick="cwSource()">查看教材原文</button></div><div class="cw-meta-grid"><div class="cw-source-card"><b>离散数学教材.pdf</b><small>第 4 章 · 图论基础 · 第 4–8 页</small></div><div class="cw-source-card"><b>第二章章节备课</b><small>重点难点 · 例题与互动 · 已确认</small></div><div class="cw-source-card"><b>教学目标</b><small>图的定义 · 目标 2 · 能力指标 A1</small></div></div></section></main><aside class="cw-rail"><section class="cw-panel prep-panel prep-chat-card"><div class="ai-chat-head"><div><h3 style="margin:0">课件 AI 助手</h3><p class="muted" style="margin:3px 0 0;font-size:11px">基于当前讲义小节和关联 PPT 辅助修改</p></div><span class="mock-chip">MOCK</span></div><div class="chat-log prep-chat-log"><div class="chat-msg assistant">当前正在编辑讲义「${h[1]}」，关联 ${h[2]}。我可以生成讲解稿、补充例题或优化课堂表达。</div><div class="chat-msg assistant"><b>推荐操作</b><br>将 PPT 的页面要点扩写为 2 分钟课堂讲解，并补充一个生活化例子。</div></div><div class="prep-chat-suggest"><button onclick="cwApply('已生成讲解稿候选')">生成讲解稿</button><button onclick="cwApply('已生成课堂提问')">补充课堂提问</button><button onclick="cwApply('已生成例题')">补充例题</button></div><div class="chat-compose"><textarea placeholder="描述要修改的讲义内容…"></textarea><button class="btn primary" onclick="cwApply('AI 正在生成讲义修改候选')">发送</button></div><div class="chat-status">AI 建议仅作用于当前讲义小节，确认后再应用</div></section></aside></div>`}
  header=function(){return `<div class="cw-head"><div><h1>课件制作</h1></div></div>`};
  function cwActions(){return `<div class="cw-courseware-actions"><button class="btn primary" onclick="cwOpenConfig()">✦ 配置后生成</button><button class="btn secondary" onclick="cwPreview()">预览</button><button class="btn secondary" onclick="cwExport()">导出</button><button class="btn secondary cw-version-top" onclick="cwOpenVersions()">页面版本 v1.0⌄</button><button class="btn primary" onclick="cwSave()">保存课件</button></div>`}
  chapterSwitcher=function(){return `<section class="cw-chapter-bar cw-chapter-bar-prep"><div class="prep-chapter-picker"><span>当前课件单元</span><div class="prep-chapter-strip"><button class="prep-chapter-arrow" onclick="cwChapter(-1)" aria-label="查看上一组章节">‹</button><div class="prep-chapter-rail">${cwChapters.map((c,i)=>`<button class="prep-chapter-pill ${i===activeChapter?'active':''}" data-chapter-index="${i}" onclick="cwChapterSelect(${i})"><b>${c.title}</b><small>${c.week}</small><i>${c.status}</i></button>`).join('')}</div><button class="prep-chapter-arrow" onclick="cwChapter(1)" aria-label="查看下一组章节">›</button></div></div></section>`};
  page=function(){return `<div class="cw-page">${header()}${chapterSwitcher()}<div class="cw-tab-actions-row">${editorTabs()}${cwActions()}</div>${mode==='ppt'?revisedEditor():handout()}</div>`};
  window.cwMode=function(m){mode=m;render()};window.cwSlide=function(i){activeSlide=i;mode='ppt';render();setTimeout(enhancePptLayout,0)};window.cwSection=function(i){mode='ppt';activeSlide=Math.min(i,slides.length-1);render();setTimeout(enhancePptLayout,0)};window.cwAddSlide=function(){slides.push([String(slides.length+1).padStart(2,'0'),'新增页面','空白页','待补充页面内容']);activeSlide=slides.length-1;mode='ppt';render();setTimeout(enhancePptLayout,0);toast('已新增空白 PPT 页面')};window.cwGenerate=function(){cwOpenConfig()};
  window.cwOpenConfig=function(){const old=document.getElementById('cwConfigModal');if(old)old.remove();const o=document.createElement('div');o.className='prep-edit-overlay';o.id='cwConfigModal';o.innerHTML=`<div class="prep-edit-modal cw-config-modal" role="dialog" aria-modal="true" aria-label="生成前配置"><div class="prep-edit-head"><div><h3>生成前配置</h3><div class="cw-muted">先确认模板、风格与页面骨架，再生成 PPT</div></div><button class="prep-edit-close" aria-label="关闭">×</button></div><div class="cw-config-body"><div class="cw-config-step"><b>1 · 模板</b><div class="cw-config-options"><button data-template="academic" class="cw-config-card active"><strong>学术青绿</strong><small>内置免费模板 · 清晰讲解</small></button><button data-template="minimal" class="cw-config-card"><strong>极简留白</strong><small>内置免费模板 · 重点突出</small></button><label class="cw-config-upload"><strong>上传我的 PPT 模板</strong><small>支持 .pptx / .potx</small><input type="file" accept=".pptx,.potx" onchange="cwUploadTemplate(this)"></label></div></div><div class="cw-config-step"><b>2 · 视觉风格与版式</b><div class="cw-config-grid"><label>风格<select id="cwStyle"><option>极简</option><option selected>学术</option><option>商务</option><option>活泼课堂</option><option>深色科技</option></select></label><label>主色<input id="cwPrimary" type="color" value="${cwConfig.primary}"></label><label>辅助色<input id="cwSecondary" type="color" value="${cwConfig.secondary}"></label><label>字体<select id="cwFont"><option selected>Microsoft YaHei</option><option>Arial</option><option>Georgia</option></select></label><label>页面比例<select id="cwRatio"><option selected>16:9</option><option>4:3</option></select></label></div></div><div class="cw-config-step"><div class="cw-config-step-head"><b>3 · 页面骨架确认</b><small>可调整顺序、删除或新增页面</small></div><div id="cwSkeleton" class="cw-skeleton-list">${cwConfig.skeleton.map((x,i)=>`<div class="cw-skeleton-item" data-index="${i}"><span>☷</span><b>${x}</b><button onclick="cwSkeletonMove(${i},-1)">↑</button><button onclick="cwSkeletonMove(${i},1)">↓</button><button onclick="cwSkeletonRemove(${i})">×</button></div>`).join('')}</div><button class="btn secondary" onclick="cwSkeletonAdd()">＋ 增加页面</button></div></div><div class="cw-config-foot"><span class="cw-muted">确认后将生成可编辑 PPT，并保留来源追溯与页面版本</span><button class="btn primary" onclick="cwConfirmConfig()">确认并生成 PPT</button></div></div>`;document.body.appendChild(o);const close=()=>o.remove();o.querySelector('.prep-edit-close').onclick=close;o.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>{o.querySelectorAll('[data-template]').forEach(x=>x.classList.remove('active'));b.classList.add('active');cwConfig.template=b.dataset.template});};
  window.cwUploadTemplate=function(input){const f=input.files&&input.files[0];if(f){cwConfig.template='upload';toast('已载入模板：'+f.name)}};
  window.cwSkeletonRender=function(){const el=document.getElementById('cwSkeleton');if(!el)return;el.innerHTML=cwConfig.skeleton.map((x,i)=>`<div class="cw-skeleton-item"><span>☷</span><b>${x}</b><button onclick="cwSkeletonMove(${i},-1)">↑</button><button onclick="cwSkeletonMove(${i},1)">↓</button><button onclick="cwSkeletonRemove(${i})">×</button></div>`).join('')};
  window.cwSkeletonMove=function(i,d){const j=i+d;if(j<0||j>=cwConfig.skeleton.length)return;[cwConfig.skeleton[i],cwConfig.skeleton[j]]=[cwConfig.skeleton[j],cwConfig.skeleton[i]];cwSkeletonRender()};window.cwSkeletonRemove=function(i){if(cwConfig.skeleton.length<=1)return toast('至少保留一个页面');cwConfig.skeleton.splice(i,1);cwSkeletonRender()};window.cwSkeletonAdd=function(){cwConfig.skeleton.push('新页面');cwSkeletonRender()};window.cwConfirmConfig=function(){const g=id=>document.getElementById(id);cwConfig.style=g('cwStyle')?.value||cwConfig.style;cwConfig.primary=g('cwPrimary')?.value||cwConfig.primary;cwConfig.secondary=g('cwSecondary')?.value||cwConfig.secondary;cwConfig.font=g('cwFont')?.value||cwConfig.font;cwConfig.ratio=g('cwRatio')?.value||cwConfig.ratio;document.getElementById('cwConfigModal')?.remove();toast('已确认配置，正在生成 '+cwConfig.skeleton.length+' 页 PPT');setTimeout(()=>toast('PPT 已生成，可继续编辑或切换风格'),700)};
  window.cwSave=function(){const old=document.getElementById('cwSaveModal');if(old)old.remove();const o=document.createElement('div');o.className='prep-edit-overlay';o.id='cwSaveModal';o.innerHTML='<div class="prep-edit-modal prep-notice-modal" role="dialog" aria-modal="true" aria-label="保存课件"><div class="prep-edit-head"><h3>保存课件</h3><button class="prep-edit-close" aria-label="关闭">×</button></div><div class="prep-edit-pane"><p style="margin:0 0 12px;color:#486866;line-height:1.7">请选择保存方式。覆盖会更新已有版本，新保存会保留当前版本并创建新的版本号。</p><label style="display:block;font-size:11px;color:#577471;margin-bottom:5px">版本号</label><input id="cwSaveVersion" class="prep-edit-textarea" style="min-height:40px;height:40px;resize:none" value="v1.1" aria-label="输入版本号"><div style="display:flex;gap:8px;margin-top:12px"><button class="btn secondary" data-overwrite>覆盖 v1.0</button><button class="btn primary" data-new>新保存</button></div></div></div>';document.body.appendChild(o);const close=()=>o.remove();o.querySelector('.prep-edit-close').onclick=close;o.querySelector('[data-overwrite]').onclick=()=>{toast('已覆盖保存为 '+(o.querySelector('#cwSaveVersion').value.trim()||'v1.0'));close()};o.querySelector('[data-new]').onclick=()=>{toast('已新保存版本 '+(o.querySelector('#cwSaveVersion').value.trim()||'v1.1'));close()};o.querySelector('#cwSaveVersion').focus()};
  window.cwOpenVersions=function(){const old=document.getElementById('cwVersionModal');if(old)old.remove();const o=document.createElement('div');o.className='prep-edit-overlay';o.id='cwVersionModal';o.innerHTML='<div class="prep-edit-modal prep-notice-modal" role="dialog" aria-modal="true" aria-label="页面版本"><div class="prep-edit-head"><h3>页面版本</h3><button class="prep-edit-close" aria-label="关闭">×</button></div><div class="prep-edit-pane"><p style="margin:0 0 12px;color:#486866;line-height:1.7">查看当前课件保留版本并切换预览。切换只改变查看上下文，不会覆盖正在编辑的内容。</p><div class="cw-version" data-version="v1.0"><div><b>v1.0 当前草稿</b><small>教师修改 · 2 分钟前 · 91 页</small></div><button class="btn secondary" data-view="v1.0">查看</button></div><div class="cw-version" data-version="ai"><div><b>AI 初稿</b><small>生成于今天 09:42 · 91 页</small></div><button class="btn secondary" data-view="ai">查看</button></div><div class="cw-version" data-version="v0.9"><div><b>v0.9 已发布</b><small>教学秘书审核 · 2026-09-01</small></div><button class="btn secondary" data-view="v0.9">查看</button></div><div id="cwVersionHint" class="chat-status" style="margin-top:10px">当前查看：v1.0 当前草稿</div></div></div>';document.body.appendChild(o);const close=()=>o.remove();o.querySelector('.prep-edit-close').onclick=close;o.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{o.querySelector('#cwVersionHint').textContent='当前查看：'+(b.dataset.view==='ai'?'AI 初稿':b.dataset.view==='v0.9'?'v0.9 已发布':'v1.0 当前草稿');toast('已切换查看 '+b.dataset.view)})};
