  function enableSlideDrag(){const canvas=document.querySelector('.cw-real-slide');if(!canvas)return;canvas.style.position='relative';canvas.querySelectorAll(':scope > *:not(.cw-edit-hint)').forEach((el,i)=>{if(el.dataset.dragReady)return;el.dataset.dragReady='1';el.draggable=false;el.classList.add('cw-movable');el.style.position='absolute';el.style.margin='0';el.style.left='28px';el.style.top=(i===0?'24px':i===1?'62px':i===2?'122px':'235px');el.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();e.stopPropagation();document.querySelectorAll('.cw-movable.cw-selected').forEach(x=>x.classList.remove('cw-selected'));el.classList.add('cw-selected');const cr=canvas.getBoundingClientRect(),er=el.getBoundingClientRect(),ox=e.clientX-er.left,oy=e.clientY-er.top;el.setPointerCapture?.(e.pointerId);const move=ev=>{const x=Math.max(8,Math.min(cr.width-el.offsetWidth-8,ev.clientX-cr.left-ox));const y=Math.max(8,Math.min(cr.height-el.offsetHeight-8,ev.clientY-cr.top-oy));el.style.left=x+'px';el.style.top=y+'px'};const up=()=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',up);toast('元素位置已更新')};el.addEventListener('pointermove',move);el.addEventListener('pointerup',up)})})}
