  window.cwSendPrompt=function(){const input=document.getElementById('cwPromptInput'),log=document.getElementById('cwChatLog'),status=document.getElementById('cwChatStatus');if(!input||!log)return;const prompt=input.value.trim();if(!prompt){if(status)status.textContent='请先描述要修改的内容。';return}const u=document.createElement('div');u.className='chat-msg user';u.textContent=prompt;log.appendChild(u);input.value='';const a=document.createElement('div');a.className='chat-msg assistant';a.textContent='我会基于当前 PPT 页和章节来源生成修改候选，原页面不会被直接覆盖。';log.appendChild(a);log.scrollTop=log.scrollHeight;if(status)status.textContent='已生成建议 · 请确认后应用';};
