  const composeV3Tuning=document.createElement('style');composeV3Tuning.textContent='.cw-compose-v3>.cw-wb-head p{display:none}.cw-v3-input{min-height:115px}.cw-v3-input textarea{height:75px}.cw-v3-input .cw-v3-send{display:none}.cw-v3-switch button:nth-child(2){order:-1}.cw-chapter-v2 .cw-chapter-meta>div span{font-size:0}.cw-chapter-v2 .cw-chapter-meta>div span:before{content:"当前课件单元";font-size:12px;font-weight:700;color:#6b8582}.cw-chapter-v2 .cw-chapter-meta>div span:after{content:" · 每课单元选择器";font-size:12px}@media(max-width:700px){.cw-v3-input{min-height:115px}.cw-v3-input textarea{height:75px}}';document.head.appendChild(composeV3Tuning);
  const composeV3FinalStyle=document.createElement('style');composeV3FinalStyle.textContent='.cw-v3-hint{display:none}.cw-v3-final-send{justify-self:center;min-width:220px}.cw-v3-template{position:relative}.cw-template-preview-link{display:block;margin:4px 3px 2px;color:#277e75;font-size:9px;text-decoration:underline;cursor:pointer}';document.head.appendChild(composeV3FinalStyle);
  const sourceInlineStyle=document.createElement('style');sourceInlineStyle.textContent='.cw-source-inline{display:flex;flex-wrap:wrap;gap:8px;padding:4px 2px}.cw-source-inline label{display:inline-flex;align-items:center;gap:5px;border:1px solid #dcebe8;border-radius:999px;background:#f8fcfb;padding:6px 9px;color:#47706e;font-size:10px}.cw-source-inline label:has(input:checked){background:#e8f8f4;border-color:#8fd7ce;color:#146f66}';document.head.appendChild(sourceInlineStyle);
  const sourceInlineObserver=new MutationObserver(()=>{const box=document.querySelector('.cw-v3-input');if(!box||cwComposeMode!=='chapter'||box.querySelector('.cw-source-inline'))return;const row=document.createElement('div');row.className='cw-source-inline';row.innerHTML='<label><input type="checkbox" checked> 教学大纲</label><label><input type="checkbox" checked> 第二章章节备课</label><label><input type="checkbox" checked> 离散数学教材.pdf</label><label><input type="checkbox"> 选择知识库</label>';box.insertBefore(row,box.querySelector('.cw-compose-send')?.parentElement||null)});sourceInlineObserver.observe(document.body,{childList:true,subtree:true});
  const templateImageObserver=new MutationObserver(()=>{document.querySelectorAll('.cw-v3-template img').forEach((img,i)=>{if(img.dataset.normalized)return;img.dataset.normalized='1';const fallback=['template_academic.jpg','template_b.png','template_s.png','template_glass.png','template_y.png'][i%5];img.src='assets/templates/'+fallback;img.onerror=()=>{img.style.visibility='hidden'}})});templateImageObserver.observe(document.body,{childList:true,subtree:true});
