  function reviewPage(){const c=cwChapters[activeChapter]||cwChapters[3];return `<div class="cw-post"><div class="cw-post-head"><div><div class="eyebrow">${c.title} / CONTENT REVIEW</div><h1>确认 PPT 内容</h1><p class="muted">先审查页面大纲、每页内容描述和来源，确认后才开始生成视觉页面。</p></div><span class="cw-flow-badge">第 1 步 / 4 · 文本审查</span></div>${legacyChapterBar()}<div class="cw-review-grid"><section class="cw-panel"><h3>页面结构与内容描述</h3><div class="cw-muted">可编辑页面结论、内容描述，或添加新的页面结构</div><div class="cw-review-list">${cwConfig.skeleton.map((x,i)=>`<article class="cw-review-card"><div class="cw-review-card-head"><span class="num">${String(i+1).padStart(2,'0')}</span><b>${x}</b></div><textarea>本页围绕“${x}”展开，给出清晰结论、课堂示例和必要的图示说明。</textarea><div class="cw-review-meta"><span>页面来源：${i%2?'章节备课':'教材第 '+(4+i)+' 页'}</span><span>教学目标：目标 ${i%3+1}</span><span>页面类型：${x}</span></div></article>`).join('')}</div><div class="cw-review-actions"><button class="btn secondary" onclick="cwReviewAdd()">＋ 添加新结构 / 新内容</button><span class="cw-muted">${cwConfig.skeleton.length} 页待确认</span></div></section><aside class="cw-panel"><h3>本章内容来源</h3><div class="cw-confirm-list"><div class="cw-confirm-item">✓ 教学大纲 · 能力指标与学时安排</div><div class="cw-confirm-item">✓ 第二章章节备课 · 重点难点、例题与互动</div><div class="cw-confirm-item">✓ 离散数学教材.pdf · 第 4 章 · 第 4–8 页</div></div><div style="margin-top:16px"><h3>审查规则</h3><p class="cw-muted" style="line-height:1.7">生成只使用当前章节已勾选来源；每页保留来源和教学目标关联，图表作为 PPT 内部元素。</p></div></aside></div><section class="cw-panel cw-review-actions"><span class="cw-muted">确认后将进入第 2 步：逐页生成 PPT，并显示实时进度</span><button type="button" class="btn primary" onclick="cwStartSlideGeneration()">确认内容并生成页面</button></section></div>`}
  function progressPage(){const c=cwChapters[activeChapter]||cwChapters[3];const done=cwProgress>=100;return `<div class="cw-post"><div class="cw-post-head"><div><div class="eyebrow">${c.title} / GENERATING</div><h1>${done?'生成完成':'正在生成本章课件'}</h1><p class="muted">${done?'页面与讲义已完成，正在准备预览编辑。':'内容已确认，AI 正在按页面结构生成 PPT 与讲义。'}</p></div><span class="cw-flow-badge">第 2–3 步 / 4 · <strong id="cwGenerationPercent">${cwProgress}%</strong></span></div><div class="cw-progress-wrap"><section class="cw-progress-card"><div style="display:flex;justify-content:space-between;align-items:center"><b>生成进度</b><span class="cw-muted"><strong id="cwGenerationCount">${Math.min(10,Math.max(1,Math.ceil(cwProgress/10)))}</strong>/10 页 · 讲义同步生成</span></div><div class="cw-progress-bar" style="margin-top:14px"><i id="cwGenerationBar" style="width:${cwProgress}%"></i></div><div class="cw-progress-steps"><div class="cw-progress-step active"><span>✓ 页面内容与来源快照</span><span>已完成</span></div><div class="cw-progress-step ${cwProgress>20?'active':''}"><span>${cwProgress>20?'✓':'⟳'} 页面结构与版式规划</span><span>${cwProgress>20?'已完成':'处理中'}</span></div><div class="cw-progress-step ${cwProgress>55?'active':''}"><span>${cwProgress>55?'✓':'○'} PPT 页面视觉渲染</span><span>${cwProgress>55?'已完成':'等待中'}</span></div><div class="cw-progress-step ${cwProgress>78?'active':''}"><span>${cwProgress>78?'✓':'○'} 讲义与讲解备注生成</span><span>${cwProgress>78?'已完成':'等待中'}</span></div><div class="cw-progress-step ${done?'active':''}"><span>${done?'✓':'○'} 质量检查与预览准备</span><span>${done?'已完成':'等待中'}</span></div></div>${done?'<div class="cw-preview-actions" style="margin-top:16px"><button class="btn primary" onclick="cwPostStage=\'preview\';render()">进入预览编辑</button></div>':''}</section></div></div>`}
  function previewPage(){const c=cwChapters[activeChapter]||cwChapters[3];return `<div class="cw-preview-shell"><div class="cw-post-head"><div><div class="eyebrow">${c.title} / PREVIEW & EDIT</div><h1>预览编辑课件</h1><p class="muted">已生成 ${cwConfig.skeleton.length} 页 PPT 与配套讲义 · 来源和教学目标已保留</p></div><span class="cw-flow-badge">第 4 步 / 4 · 预览编辑</span></div>${legacyChapterBar()}<div class="cw-preview-grid"><aside class="cw-panel cw-preview-nav">${cwConfig.skeleton.map((x,i)=>`<button class="cw-preview-thumb ${i===0?'active':''}">${String(i+1).padStart(2,'0')} · ${x}</button>`).join('')}</aside><section class="cw-preview-canvas"><span class="cw-slide-kicker">${c.title}</span><h2>图论基础 · 课堂课件</h2><p>本章围绕核心概念、典型例题和课堂互动组织内容，页面已应用所选模板和视觉规则。</p><div class="cw-diagram"><strong>页面内图表组件</strong>结点集 V　↔　边集 E</div></section></div><div class="cw-preview-actions"><button class="btn secondary" onclick="cwStartSlideGeneration()">重新生成</button><button class="btn secondary" onclick="cwWorkbenchGenerated=true;mode='ppt';render();setTimeout(enhancePptLayout,0)">进入 PPT 编辑</button><button class="btn primary" onclick="cwSave()">保存版本</button></div></div>`}
  window.cwReviewAdd=function(){cwConfig.skeleton.push('新增教学内容');render()};window.cwReviewDelete=function(i){if(cwConfig.skeleton.length<=1)return toast('至少保留一个页面');cwConfig.skeleton.splice(i,1);render();toast('已删除该页面结构')};window.cwStartSlideGeneration=function(){if(cwPostStage==='progress')return;if(typeof previewDeckObserver!=='undefined')previewDeckObserver.disconnect();cwPostStage='progress';cwProgress=0;clearInterval(cwProgressTimer);render();cwProgressTimer=setInterval(()=>{cwProgress=Math.min(100,cwProgress+10);const bar=document.getElementById('cwGenerationBar'),pct=document.getElementById('cwGenerationPercent'),count=document.getElementById('cwGenerationCount');if(bar)bar.style.width=cwProgress+'%';if(pct)pct.textContent=cwProgress+'%';if(count)count.textContent=Math.min(10,Math.max(1,Math.ceil(cwProgress/10)));if(cwProgress>=100){clearInterval(cwProgressTimer);cwProgressTimer=null;cwPostStage='preview';render()}},380)};
  window.cwComposeSend=function(){cwComposePrompt=document.getElementById('cwComposePrompt')?.value||'';cwComposeStage='review';cwPostStage='review';render()};
  document.addEventListener('click',e=>{const b=e.target.closest?.('.cw-compose .cw-wb-bottom .btn');if(!b)return;e.preventDefault();e.stopImmediatePropagation();cwStartSlideGeneration()},{capture:true});
  page=function(){return cwWorkbenchGenerated?coursewareEditorPage():cwPostStage==='review'&&cwComposeStage==='review'?reviewPage():cwPostStage==='progress'?progressPage():cwPostStage==='preview'?previewPage():compactComposePage()};
  const templatePreviewObserver=new MutationObserver(()=>{document.querySelectorAll('.cw-v3-template').forEach((card,i)=>{if(card.querySelector('.cw-template-preview-link'))return;const link=document.createElement('span');link.className='cw-template-preview-link';link.textContent='查看模板预览';link.onclick=e=>{e.stopPropagation();window.cwPreviewTemplate(i)};card.appendChild(link)})});templatePreviewObserver.observe(document.body,{childList:true,subtree:true});
  const reviewCardObserver=new MutationObserver(()=>{document.querySelectorAll('.cw-review-card-head').forEach((head,i)=>{if(head.querySelector('.cw-review-delete'))return;const b=document.createElement('button');b.className='icon-btn cw-review-delete';b.type='button';b.title='删除此页';b.textContent='×';b.onclick=e=>{e.stopPropagation();window.cwReviewDelete(i)};head.appendChild(b)})});reviewCardObserver.observe(document.body,{childList:true,subtree:true});
  window.cwPreviewTemplate=function(i){const imgs=['template_academic.jpg','template_b.png','template_s.png','template_glass.png','template_y.png'];const names=['学术严谨','商务简洁','活泼课堂','极简留白','深色科技'];const old=document.getElementById('cwTemplatePreviewModal');if(old)old.remove();const o=document.createElement('div');o.id='cwTemplatePreviewModal';o.className='prep-edit-overlay';o.innerHTML='<div class="prep-edit-modal" style="width:min(760px,calc(100vw - 28px))"><div class="prep-edit-head"><div><h3>'+names[i%names.length]+' · 模板预览</h3><div class="cw-muted">Banana Slides 基础模板 · 可用于本章课件生成</div></div><button class="prep-edit-close" aria-label="关闭">×</button></div><div style="padding:16px"><img src="assets/templates/'+imgs[i%imgs.length]+'" alt="'+names[i%names.length]+'模板大图" style="display:block;width:100%;max-height:420px;object-fit:contain;border:1px solid #e3efed;border-radius:10px;background:#f8fcfb"><p class="cw-muted" style="line-height:1.7;margin:12px 0 0">适合页面：封面、概念讲解、例题、图表与课堂互动。选中后会作为本章默认视觉参考。</p></div></div>';document.body.appendChild(o);o.querySelector('.prep-edit-close').onclick=()=>o.remove()};
  document.addEventListener('click',e=>{const b=e.target.closest?.('.cw-v3-switch button');if(!b)return;e.preventDefault();e.stopImmediatePropagation();cwComposeMode=b.textContent.includes('一句话')?'idea':'chapter';render()},{capture:true});
  function composeV3Page(){const c=cwChapters[activeChapter]||cwChapters[3];const t=[['academic-formal','学术严谨','/prototype/assets/templates/academic-formal.webp'],['business-simple','商务简洁','/prototype/assets/templates/business-simple.webp'],['creative-fun','活泼课堂','/prototype/assets/templates/creative-fun.webp'],['minimalist-clean','极简留白','/prototype/assets/templates/minimalist-clean.webp'],['tech-modern','深色科技','/prototype/assets/templates/tech-modern.webp']];return `<div class="cw-compose-v3"><div class="cw-wb-head"><div><div class="eyebrow">${c.title} / COURSEWARE</div><h1>课件生成工作台</h1><p class="muted">选择生成方式，输入要求，再配置生成规则。</p></div></div>${legacyChapterBar()}<div class="cw-v3-main"><div class="cw-v3-switch"><button class="${cwComposeMode==='chapter'?'active':''}" onclick="cwComposeMode='chapter';render()">⌘ 从章节上下文生成</button><button class="${cwComposeMode==='idea'?'active':''}" onclick="cwComposeMode='idea';render()">✦ 一句话生成</button></div><section class="cw-v3-input"><textarea id="cwComposePrompt" placeholder="描述你想生成的课件，例如：围绕图论基础，生成一套包含问题导入、概念讲解、例题、课堂互动和作业的 10 页课件">${cwComposePrompt}</textarea><div class="cw-v3-input-foot"><small>${cwComposeMode==='chapter'?'将使用当前章节可用的备课、教学大纲和教材上下文':'AI 将根据你的描述生成大纲与逐页内容'}</small><button class="cw-v3-send" onclick="cwComposeSend()" aria-label="生成 PPT">↑</button></div></section><section class="cw-panel cw-v3-rules"><h3>生成规则</h3><div class="cw-v3-template-row">${t.map(x=>`<button class="cw-v3-template ${cwWorkbenchTemplate===x[0]?'active':''}" onclick="cwWorkbenchTemplate='${x[0]}';render()"><img src="${x[2]}" alt="${x[1]}模板"><b>${x[1]}</b><small>基础模板</small></button>`).join('')}<label class="cw-v3-upload">＋ 上传模板<input type="file" accept=".pptx,.potx,.pdf" onchange="cwWorkbenchUpload(this)"></label></div><div class="cw-v3-rule-grid"><label class="cw-v3-rule">页面比例<select><option>16:9</option><option>4:3</option></select></label><label class="cw-v3-rule">PPT 风格<select><option>学术严谨</option><option>商务简洁</option><option>活泼课堂</option><option>深色科技</option><option>极简留白</option><option>现代科技</option></select></label><label class="cw-v3-rule">图标策略<select><option>线性图标，保持克制</option><option>AI 自动生成</option><option>使用教材图示</option><option>不使用图标</option></select></label><label class="cw-v3-rule">生成策略<select><option>10 页 · 每页 2–4 条</option><option>12 页 · 每页 2–4 条</option><option>15 页 · 内容更丰富</option></select></label></div><div class="cw-v3-hint"><span>✓ 保留来源追溯</span><span>✓ PPT 内部可编辑图表</span><span>✓ 可继续生成讲义和讲解备注</span></div></section></div></div>`}
  const composeModeTitleStyle=document.createElement('style');composeModeTitleStyle.textContent='.cw-compose-shell .cw-v3-mode-title{display:flex;align-items:center;gap:8px;justify-self:start;padding:0 0 9px;border-bottom:2px solid #35ab9a;color:#164c49;font-size:16px;font-weight:700;letter-spacing:.01em}.cw-compose-shell .cw-v3-mode-star{display:inline-grid;place-items:center;width:22px;height:22px;border-radius:7px;background:#e8f8f4;color:#0b9c8c;font-size:14px;line-height:1}';document.head.appendChild(composeModeTitleStyle);
  let cwHidePostChapter=false;
  legacyChapterBar=function(){if(cwHidePostChapter)return '';return `<section class="cw-chapter-bar cw-chapter-v2"><div class="cw-chapter-meta"><div><span>当前课件单元</span></div></div><div class="cw-chapter-picker"><div class="cw-chapter-rail">${cwChapters.slice(0,4).map((c,i)=>`<button class="cw-chapter-pill ${i===activeChapter?'active':''}" onclick="cwComposeChapter(${i})"><b>${c.title}</b><small>${c.week}</small><i>${c.status}</i></button>`).join('')}</div></div></section>`};
