  const compactRailStyle=document.createElement('style');compactRailStyle.textContent='.cw-compose-shell{display:grid;grid-template-columns:minmax(0,1fr) 292px;gap:14px;align-items:start}.cw-compose-shell .cw-v3-main{max-width:none}.cw-status-rail{display:grid;gap:9px}.cw-status-rail h3{margin:0;font-size:13px;color:#164c49}.cw-status-card{padding:11px;border:1px solid #dfebe9;border-radius:12px;background:#fff;display:grid;gap:8px;box-shadow:0 5px 15px rgba(24,76,73,.04)}.cw-status-head{display:flex;justify-content:space-between;align-items:center;gap:8px}.cw-status-head b{font-size:11px}.cw-status-badge{font-size:9px;border-radius:999px;padding:4px 7px;background:#e9f8f5;color:#167a70}.cw-status-card.generating .cw-status-badge{background:#eef4ff;color:#4b79b8}.cw-status-card.saved .cw-status-badge{background:#f2f3f3;color:#6d7b7a}.cw-status-body{display:flex;gap:9px;align-items:center}.cw-status-thumb{width:72px;height:48px;border-radius:6px;object-fit:cover;border:1px solid #e0ebe9;background:#f4f9f7}.cw-status-info{min-width:0}.cw-status-info strong,.cw-status-info small{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.cw-status-info strong{font-size:11px;color:#315b58}.cw-status-info small{font-size:9px;color:#819995;margin-top:4px}.cw-status-progress{height:4px;border-radius:99px;background:#e5edf4;overflow:hidden}.cw-status-progress i{display:block;height:100%;width:58%;background:#6b9dde}.cw-status-actions{display:flex;gap:5px}.cw-status-actions button{border:1px solid #dcebe8;border-radius:6px;background:#fff;color:#39716d;padding:5px 7px;font-size:9px;cursor:pointer}.cw-status-actions button.primary{background:#164c49;color:#fff;border-color:#164c49}.cw-rail-note{font-size:10px;color:#829693;line-height:1.55;padding:3px 2px}@media(max-width:980px){.cw-compose-shell{grid-template-columns:minmax(0,1fr) 250px}}@media(max-width:760px){.cw-compose-shell{grid-template-columns:1fr}.cw-status-rail{display:flex;overflow:auto;padding-bottom:4px}.cw-status-rail h3,.cw-rail-note{display:none}.cw-status-card{min-width:220px}}';document.head.appendChild(compactRailStyle);
  const compactRailFix=document.createElement('style');compactRailFix.textContent='.cw-compose-shell{grid-template-columns:minmax(0,1fr) 204px}.cw-compose-shell>div:first-child{display:contents}.cw-compose-shell>div:first-child>.cw-wb-head{grid-column:1/-1}.cw-compose-shell>div:first-child>.cw-chapter-bar{grid-column:1/-1}.cw-compose-shell>div:first-child>.cw-v3-main{grid-column:1;min-width:0}.cw-status-rail{grid-column:2;grid-row:3}.cw-status-card{min-width:0}@media(max-width:980px){.cw-compose-shell{grid-template-columns:minmax(0,1fr) 180px}}@media(max-width:760px){.cw-compose-shell{display:block}.cw-compose-shell>div:first-child{display:block}.cw-status-rail{margin-top:14px}}';document.head.appendChild(compactRailFix);
